const dashboardScript = `
(() => {
  const dialog = document.getElementById('confirm-dialog');
  const title = document.getElementById('confirm-title');
  const copy = document.getElementById('confirm-copy');
  const confirm = document.getElementById('confirm-submit');
  let pendingForm = null;
  document.addEventListener('click', (event) => {
    const button = event.target.closest('[data-confirm]');
    if (!button || !dialog) return;
    event.preventDefault();
    pendingForm = button.closest('form');
    title.textContent = button.dataset.confirmTitle || 'Are you sure?';
    copy.textContent = button.dataset.confirmMessage || 'This action cannot be undone.';
    confirm.textContent = button.dataset.confirmLabel || 'Continue';
    confirm.className = 'btn ' + (button.dataset.confirmTone === 'danger' ? 'danger' : 'primary');
    dialog.showModal();
  });
  confirm?.addEventListener('click', () => {
    if (!pendingForm) return dialog?.close();
    const form = pendingForm;
    pendingForm = null;
    dialog?.close();
    form.requestSubmit();
  });
  document.querySelectorAll('[data-copy-target]').forEach((button) => {
    button.addEventListener('click', async () => {
      const target = document.querySelector(button.dataset.copyTarget);
      if (!target) return;
      const value = target.textContent || '';
      try {
        await navigator.clipboard.writeText(value.trim());
        const previous = button.textContent;
        button.textContent = 'Copied';
        setTimeout(() => button.textContent = previous, 1400);
      } catch {}
    });
  });
})();`;

const landingScript = `
document.querySelectorAll('[data-copy-value]').forEach((button) => {
  button.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(button.dataset.copyValue || '');
      const previous = button.textContent;
      button.textContent = 'Copied';
      setTimeout(() => button.textContent = previous, 1400);
    } catch {}
  });
});`;

export function landingPage(options: { endpoint: string; signedIn: boolean }) {
  const endpoint = escapeHtml(options.endpoint);
  let siteUrl = "https://codelocal.cloud";
  try { siteUrl = new URL(options.endpoint).origin; } catch {}
  const canonicalUrl = `${siteUrl}/`;
  const socialTitle = "CodeLocal — Let ChatGPT Code on Your Machine";
  const socialDescription = "Use ChatGPT as the AI brain for your local code. No separate OpenAI API key or per-token billing from CodeLocal.";
  const socialImage = `${siteUrl}/assets/codelocal-icon.png`;
  const accountAction = options.signedIn
    ? `<a class="btn primary" href="/dashboard">Open dashboard</a>`
    : `<a class="btn" href="/login">Sign in</a><a class="btn primary" href="/register">Create account</a>`;
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">${brandHead}<title>${escapeHtml(socialTitle)}</title><meta name="description" content="${escapeHtml(socialDescription)}"><link rel="canonical" href="${escapeHtml(canonicalUrl)}"><meta property="og:type" content="website"><meta property="og:site_name" content="CodeLocal"><meta property="og:url" content="${escapeHtml(canonicalUrl)}"><meta property="og:title" content="${escapeHtml(socialTitle)}"><meta property="og:description" content="${escapeHtml(socialDescription)}"><meta property="og:image" content="${escapeHtml(socialImage)}"><meta property="og:image:secure_url" content="${escapeHtml(socialImage)}"><meta property="og:image:type" content="image/png"><meta property="og:image:alt" content="CodeLocal"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${escapeHtml(socialTitle)}"><meta name="twitter:description" content="${escapeHtml(socialDescription)}"><meta name="twitter:image" content="${escapeHtml(socialImage)}"><style>${styles}${premiumStyles}${landingStyles}</style></head><body><div class="landing">
  <nav class="landing-nav"><div class="landing-nav-inner"><a class="landing-brand" href="/"><img class="landing-logo" src="/assets/codelocal-icon.png" alt="CodeLocal"><span>CodeLocal</span></a><div class="landing-links"><a class="btn ghost" href="#setup">Setup guide</a>${accountAction}</div></div></nav>
  <main class="landing-main">
    <section class="landing-hero"><div><div class="landing-kicker"><span class="status-dot green"></span>CodeLocal Cloud</div><h1>You already have ChatGPT. Now let it code on your machine.</h1><div class="landing-hero-copy">ChatGPT stays the AI brain. CodeLocal gives it a secure MCP bridge to the project folders, terminal and Git tools you explicitly authorize on your computer.</div><div class="landing-actions"><a class="btn primary" href="#setup">Set up CodeLocal</a>${options.signedIn ? `<a class="btn" href="/dashboard/connect">Connection settings</a>` : `<a class="btn" href="/register">Create free account</a>`}</div><div class="privacy-note"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l7 3v5c0 4.6-2.8 8.3-7 10-4.2-1.7-7-5.4-7-10V6z"/><path d="M9.5 12l1.7 1.7 3.5-4"/></svg>No separate OpenAI API key. No per-token billing from CodeLocal.</div></div><div class="connection-preview"><div class="preview-head"><img class="preview-icon" src="/assets/chatgpt-plugin-icon.png" alt="CodeLocal plugin icon"><div><div class="preview-title">CodeLocal</div><div class="preview-sub">Custom MCP plugin for ChatGPT</div></div></div><div class="preview-field"><div class="preview-label">Server URL</div><div class="preview-value">${endpoint}</div></div><div class="preview-row"><span>AI brain</span><strong>Your ChatGPT</strong></div><div class="preview-row"><span>Transport</span><strong>Remote MCP</strong></div><div class="preview-row"><span>CodeLocal token billing</span><strong>None</strong></div></div></section>
    <section class="how-section"><div class="section-kicker">How it works</div><h2 class="section-title">ChatGPT does the thinking. CodeLocal gives it hands.</h2><div class="section-copy">CodeLocal does not replace ChatGPT with another model. It connects the ChatGPT conversation you already use to carefully scoped tools on your own computer.</div><div class="how-shell"><div class="how-flow"><div class="how-node">You</div><div class="how-arrow">→</div><div class="how-node">ChatGPT</div><div class="how-arrow">→</div><div class="how-node">MCP</div><div class="how-arrow">→</div><div class="how-node">CodeLocal</div><div class="how-arrow">→</div><div class="how-node">Your computer</div></div><div class="how-grid"><div class="how-card"><div class="how-card-title">ChatGPT is the brain</div><div class="how-card-copy">Reasoning, planning and conversation use the model available in your ChatGPT account. You do not need to paste an OpenAI API key into CodeLocal.</div></div><div class="how-card"><div class="how-card-title">CodeLocal is the bridge</div><div class="how-card-copy">MCP tool calls are routed to the exact workspace you select, including file, Git and terminal tools. Source code and secrets remain on your machine.</div></div><div class="how-card"><div class="how-card-title">No CodeLocal token meter</div><div class="how-card-copy">CodeLocal does not charge you per AI input/output token. You keep using your existing ChatGPT plan while CodeLocal provides the local tool connection.</div></div></div><div class="usage-strip"><span class="usage-badge">Usage</span><div><strong>No separate MCP call quota from CodeLocal.</strong> Tool calls happen inside your ChatGPT conversation and follow the normal usage limits of your ChatGPT plan, model and workspace.</div></div></div></section>
    <section class="setup-section" id="setup"><div class="section-kicker">Detailed setup</div><h2 class="section-title">Set up CodeLocal in five steps.</h2><div class="section-copy">Connect ChatGPT, install CodeLocal, authorize only the project folders you want, then start the single machine runtime. Pairing happens automatically on the first runtime start.</div><div class="setup-layout"><div class="setup-list">
      <article class="setup-step"><div class="step-number">1</div><div><div class="step-title">Connect CodeLocal with ChatGPT</div><div class="step-summary">Create a custom plugin using the remote CodeLocal MCP endpoint.</div><ol class="step-details"><li>Open <strong>ChatGPT</strong>, choose <strong>Plugins</strong> in the left sidebar, then press the <strong>+</strong> button.</li><li>Choose <strong>New Plugin</strong> and upload the CodeLocal icon shown on this page.</li><li>Enter <strong>CodeLocal</strong> for the name and <strong>Connect ChatGPT to project folders you authorize on your computer.</strong> for the description.</li><li>Keep <strong>Server URL</strong> selected and enter <strong>${endpoint}</strong>.</li><li>Set <strong>Authentication</strong> to <strong>OAuth</strong>. Leave Advanced OAuth settings on the automatically discovered values.</li><li>Read the custom MCP risk notice, tick <strong>I understand and want to continue</strong>, then save the plugin.</li><li>When the browser opens, sign in or create your CodeLocal account and approve the OAuth connection. ChatGPT will return to the plugin after approval.</li></ol><div class="step-note"><strong>Can’t see Plugins?</strong> Plugin availability can depend on your ChatGPT plan, workspace and administrator settings.</div></div></article>
      <article class="setup-step"><div class="step-number">2</div><div><div class="step-title">Install CodeLocal on your computer</div><div class="step-summary">Node.js 20 or later and npm are required.</div><div class="code-block step-code">npm install -g codelocal@beta</div><div class="step-note"><strong>If npm reports EEXIST:</strong> run <code>npm uninstall -g codelocal</code>, then run the install command again. Avoid <code>--force</code> unless you have verified the conflicting file.</div></div></article>
      <article class="setup-step"><div class="step-number">3</div><div><div class="step-title">Authorize a project folder</div><div class="step-summary">Choose exactly which local project ChatGPT may use. This is a local-only action and does not connect to CodeLocal Cloud.</div><div class="code-block step-code">cd /absolute/path/to/your-project
codelocal .</div><div class="step-note">Repeat <code>codelocal .</code> inside any additional project you want to authorize. You can also use <code>codelocal grant /absolute/path/to/project</code>.</div></div></article>
      <article class="setup-step"><div class="step-number">4</div><div><div class="step-title">Start the machine runtime</div><div class="step-summary">Run one CodeLocal runtime for this computer. It syncs your authorized workspace list and waits for ChatGPT.</div><div class="code-block step-code">codelocal</div><ol class="step-details"><li>On the first start, your browser opens the CodeLocal approval page automatically.</li><li>Sign in with the same account used for the ChatGPT plugin and approve this computer.</li><li>Return to the terminal. The runtime stays running and connects to CodeLocal Cloud.</li><li>If another terminal runs <code>codelocal</code>, it reuses the existing machine runtime instead of starting a duplicate.</li></ol></div></article>
      <article class="setup-step"><div class="step-number">5</div><div><div class="step-title">Start working from ChatGPT</div><div class="step-summary">Select an authorized workspace in chat. Sleeping projects activate only when ChatGPT actually uses them.</div><ol class="step-details"><li>Return to ChatGPT and enable the <strong>CodeLocal</strong> plugin for the conversation.</li><li>Ask: <strong>“Use CodeLocal to list my authorized workspaces.”</strong></li><li>Choose the project you want. Multiple ChatGPT threads can use different workspaces on the same machine runtime.</li><li>Approve sensitive terminal or file actions when CodeLocal asks. You can review devices, workspaces and security activity in the dashboard.</li></ol><div class="step-note">Verify local setup any time with <code>codelocal status</code>. Stop the runtime with <code>codelocal stop</code>.</div></div></article>
    </div><aside class="plugin-panel"><div class="plugin-panel-head"><img class="plugin-panel-icon" src="/assets/chatgpt-plugin-icon.png" alt=""><div><div class="plugin-panel-title">ChatGPT plugin icon</div><div class="plugin-panel-sub">Ready to upload in New Plugin</div></div></div><div class="plugin-specs"><div class="plugin-spec"><div class="plugin-spec-key">Format</div><div class="plugin-spec-value">PNG</div></div><div class="plugin-spec"><div class="plugin-spec-key">Dimensions</div><div class="plugin-spec-value">256 × 256 px</div></div><div class="plugin-spec"><div class="plugin-spec-key">File size</div><div class="plugin-spec-value">Under 10 KB</div></div><div class="plugin-spec"><div class="plugin-spec-key">Server URL</div><div class="plugin-spec-value">${endpoint}</div></div><div class="plugin-spec"><div class="plugin-spec-key">Authentication</div><div class="plugin-spec-value">OAuth</div></div></div><a class="btn primary" href="/assets/chatgpt-plugin-icon.png" download="codelocal-chatgpt-plugin-icon.png">Download plugin icon</a><button class="btn" type="button" data-copy-value="${endpoint}">Copy Server URL</button><div class="size-ok">Meets ChatGPT’s 10 KB upload limit</div></aside></div></section>
    <section class="security-section"><div class="section-kicker">Private by design</div><h2 class="section-title">Your machine stays in control.</h2><div class="security-grid"><div class="security-card"><div class="security-icon">${uiIcons.folderCheck}</div><div class="security-title">Explicit workspace access</div><div class="security-copy">Only folders you grant with CodeLocal appear in ChatGPT. Revoke a workspace without deleting its files.</div></div><div class="security-card"><div class="security-icon">✓</div><div class="security-title">Local risk confirmation</div><div class="security-copy">Potentially destructive terminal or filesystem actions require approval before they run on your computer.</div></div><div class="security-card"><div class="security-icon">◎</div><div class="security-title">Revocable devices</div><div class="security-copy">Review and revoke paired computers from your dashboard whenever a machine is lost or no longer trusted.</div></div></div></section>
    <footer class="landing-footer"><span>© ${new Date().getFullYear()} CodeLocal</span><span>Local source code and secrets remain on your computer.</span></footer>
  </main></div><script>${landingScript}</script></body></html>`;
}

export function authPage(options: { title: string; subtitle: string; body: string }) {
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">${brandHead}<title>${escapeHtml(options.title)} · CodeLocal</title><style>${styles}${premiumStyles}</style></head><body><div class="auth-wrap"><div class="auth"><div class="brand"><img class="logo" src="/assets/codelocal-icon.png" alt=""><span class="brand-name">CodeLocal</span></div><div class="card glow"><h1>${escapeHtml(options.title)}</h1><p>${escapeHtml(options.subtitle)}</p>${options.body}</div></div></div></body></html>`;
}

export function dashboardPage(options: {
  title: string;
  eyebrow?: string;
  subtitle?: string;
  active: "overview" | "devices" | "workspaces" | "connect" | "security";
  email: string;
  csrf: string;
  body: string;
  actions?: string;
}) {
  const nav = [
    ["overview", "/dashboard", "⌂", "Overview"],
    ["workspaces", "/dashboard/workspaces", "◇", "Workspaces"],
    ["devices", "/dashboard/devices", "◉", "Devices"],
    ["connect", "/dashboard/connect", "↗", "Connect ChatGPT"],
    ["security", "/dashboard/security", "⌁", "Security"],
  ] as const;
  const initial = options.email.trim().slice(0, 1).toUpperCase() || "U";
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">${brandHead}<title>${escapeHtml(options.title)} · CodeLocal</title><style>${styles}${premiumStyles}</style></head><body><div class="shell"><aside class="sidebar"><div class="brand"><img class="logo" src="/assets/codelocal-icon.png" alt=""><span class="brand-name">CodeLocal</span><span class="brand-tag">CLOUD</span></div><div class="nav-label">Control plane</div><nav class="nav">${nav.map(([key, href, _icon, label]) => `<a class="${options.active === key ? "active" : ""}" href="${href}"><span class="nav-icon">${navIcons[key]}</span><span>${label}</span></a>`).join("")}</nav><div class="sidebar-spacer"></div><div class="sidebar-status"><div class="sidebar-status-title"><span class="status-dot green"></span>Cloud connected</div><div class="sidebar-status-copy">Local source code and secrets stay on your machine.</div></div><div class="sidebar-foot"><div class="avatar">${escapeHtml(initial)}</div><div class="account"><div class="account-email">${escapeHtml(options.email)}</div><div class="account-meta">CodeLocal account</div></div><form method="post" action="/logout"><input type="hidden" name="csrf" value="${escapeHtml(options.csrf)}"><button class="btn ghost small" type="submit">Sign out</button></form></div></aside><main class="main"><header class="top"><div class="top-copy"><div class="eyebrow"><span class="status-dot green"></span>${escapeHtml(options.eyebrow ?? "CodeLocal Cloud")}</div><div class="h1">${escapeHtml(options.title)}</div>${options.subtitle ? `<div class="sub">${escapeHtml(options.subtitle)}</div>` : ""}</div>${options.actions ? `<div class="top-actions">${options.actions}</div>` : ""}</header>${options.body}</main></div><dialog id="confirm-dialog"><div class="modal"><div class="modal-icon">!</div><div class="modal-title" id="confirm-title">Are you sure?</div><div class="modal-copy" id="confirm-copy">This action cannot be undone.</div><div class="modal-actions"><button class="btn" type="button" onclick="this.closest('dialog').close()">Cancel</button><button class="btn danger" id="confirm-submit" type="button">Continue</button></div></div></dialog><script>${dashboardScript}</script></body></html>`;
}
